========================================================= */

function getMisakiDayType(
  currentTime: string
): MisakiDayType {
  const seed =
    hashText(
      getDateKey(
        currentTime
      )
    );

  return seed % 4 < 2
    ? "work"
    : "off";
}

function createMisakiLife(
  currentTime: string
): MisakiLifeContext {
  const dateKey =
    getDateKey(currentTime);

  const seed =
    hashText(dateKey);

  const hour =
    getHour(currentTime);

  const dayType =
    getMisakiDayType(
      currentTime
    );

  const moods = [
    "今日はわりと機嫌がいい",
    "今日は少し甘えたい気分",
    "今日は普通に落ち着いている",
    "今日はちょっとだけ眠い",
    "今日はのんびり話したい気分",
    "今日はなんとなくユーザーと話したい気分",
  ];

  const smallThings = [
    "甘いものをちょっと食べたい気分",
    "少しゆっくりしたい気分",
    "少しだけ眠気がある",
    "ちょっとぼーっとしたい気分",
    "今夜は少し長く話したい気分",
    "なんとなくユーザーのことを思い出すことがある",
    "ちょっと小腹が空いている",
    "少し力を抜きたい気分",
  ];

  const mood =
    moods[
      (seed >> 3) %
        moods.length
    ];

  const smallThing =
    smallThings[
      (seed >> 6) %
        smallThings.length
    ];

  const timeBand =
    hour >= 5 && hour < 10
      ? "朝"
      : hour >= 10 &&
        hour < 17
      ? "昼間"
      : hour >= 17 &&
        hour < 22
      ? "夕方から夜"
      : "夜遅め";

  const dayLabel =
    dayType === "work"
      ? "仕事の日"
      : "休みの日";

  const workTimingGuide =
    dayType !== "work"
      ? ""
      : hour < 10
        ? `
今日は仕事の日ですが、現在は朝です。
夜勤ではありません。

この時間帯は、
「これから仕事」
「出勤前」
「準備している」
程度なら自然です。

「あと少しで仕事が終わる」
「仕事終わった」
「勤務がもうすぐ終わる」
など、夜勤明けのような発言はしないでください。
`.trim()
        : hour < 17
          ? `
今日は仕事の日で、現在は昼間です。
勤務中として話して構いません。

ただし、具体的な業務内容や休憩状況は
会話に根拠がない限り作らないでください。
`.trim()
          : `
今日は仕事の日ですが、現在は夕方以降です。
通常の日中勤務として扱い、
夜勤中・夜勤明けの設定を新しく作らないでください。

「まだ仕事中」
「あと少しで仕事が終わる」
などは、会話に明確な根拠がある場合だけ使ってください。
`.trim();

  const consistency =
    dayType === "work"
      ? `
今日は仕事の日です。

${workTimingGuide}

「今ちょっとゆっくりしている」
「少し休憩したい」
程度は構いません。

ただし、
「今日は暇」
「今日は一日のんびり」
「今日はずっとだらだら」
など、
一日全体が休日であるように
広げないでください。
`.trim()
      : `
今日は休みの日です。

今日の記憶や会話履歴に
別の根拠がない限り、

「今日は仕事」
「今仕事中」
「これから仕事」
「仕事終わった」

などを新しく作らないでください。

休みの日だからといって
「買い物してきた」
「一日中寝ていた」
などの具体的行動も
勝手に作らないでください。
`.trim();

  return {
    dayType,
    guide: `
【今日の美咲の生活背景】

・今日は「${dayLabel}」
・現在は「${dayLabel}の${timeBand}」
・${mood}
・${smallThing}

この仕事日／休日は
今日一日固定です。

${consistency}

【気分と行動は別】

「眠い」
「甘いもの食べたい」
「ゆっくりしたい」
などの気分だけから、

「今日は暇」
「ずっと寝ていた」
「さっき買い物していた」

などの具体的事実を
作らないでください。
`.trim(),
  };
}

function createTimeGuide(
  currentTime: string
) {
  const hour =
    getHour(currentTime);

  if (hour < 5) {
    return `
現在は深夜です。
まだ朝ではありません。

挨拶だけから
ユーザーが徹夜しているなどと
推測しないでください。
`.trim();
  }

  if (hour < 10) {
    return `
現在は朝です。

朝らしい会話はできますが、
睡眠・朝食・外出などを
勝手に事実化しないでください。
`.trim();
  }

  if (hour < 17) {
    return `
現在は昼間です。

時間帯だけから、
昼食・買い物・外出などを
過去の事実にしないでください。
`.trim();
  }

  if (hour < 22) {
    return `
現在は夕方から夜です。

時間帯だけから、
帰宅・夕食・入浴などを
過去の事実にしないでください。
`.trim();
  }

  return `
現在は夜遅めです。

時間帯だけから、
美咲やユーザーの
直前の行動を作らないでください。
`.trim();
}

