function publicChatResult(result: Record<string, unknown>) {
  const { relationshipPointDelta: _internalRelationshipPointDelta, ...publicResult } = result;
  return publicResult;
}

export async function POST(
  request: Request
) {
  const maintenance = await maintenanceResponse();
  if (maintenance) return maintenance;
  const traceId =
    crypto.randomUUID()
      .slice(0, 8);
  const requestStartedAt =
    Date.now();

  async function measureStage<T>(
    stage: string,
    task: () => Promise<T>
  ): Promise<T> {
    const startedAt =
      Date.now();

    try {
      const result =
        await task();

      console.log(
        "CHAT STAGE:",
        {
          traceId,
          stage,
          elapsedMs:
            Date.now() -
            startedAt,
          ok: true,
        }
      );

      return result;
    } catch (error) {
      console.error(
        "CHAT STAGE:",
        {
          traceId,
          stage,
          elapsedMs:
            Date.now() -
            startedAt,
          ok: false,
          error:
            error instanceof Error
              ? error.message
              : String(error),
        }
      );

      throw error;
    }
  }

  let chargedRequestId:
    string | null = null;
  let chargedSupabase:
    SupabaseClient | null = null;

  async function refundIfCharged() {
    if (
      !chargedRequestId ||
      !chargedSupabase
    ) {
      return null;
    }

    const refunded =
      await refundDailyMessage(
        chargedSupabase,
        chargedRequestId
      );

    chargedRequestId = null;
    chargedSupabase = null;

    return refunded;
  }

  try {
    let {
      message,
      history,
      memory,
      currentTime,
      requestId,
      temporaryState,
      misakiTodayMemory,
    } =
      await measureStage(
        "request-json",
        () =>
          request.json()
      );

    if (
      !message ||
      typeof message !==
        "string"
    ) {
      return Response.json(
        {
          error:
            "メッセージを入力してね。",
        },
        {
          status: 400,
        }
      );
    }

    const apiKey =
      process.env
        .GEMINI_API_KEY;

    if (!apiKey) {
      return Response.json(
        {
          error:
            "今ちょっと調子が悪いみたい。少し待ってからもう一度話しかけてね。",
        },
        {
          status: 500,
        }
      );
    }

    const authorization =
      request.headers.get(
        "authorization"
      ) ?? "";

    if (
      !authorization.startsWith(
        "Bearer "
      )
    ) {
      return Response.json(
        {
          error:
            "ログイン情報を確認できませんでした。ページを再読み込みしてね。",
        },
        {
          status: 401,
        }
      );
    }

    const accessToken =
      authorization
        .slice(
          "Bearer ".length
        )
        .trim();

    const supabase =
      createAuthenticatedSupabase(
        accessToken
      );

    const {
      data: userData,
      error: userError,
    } =
      await measureStage(
        "auth-get-user",
        () =>
          supabase.auth.getUser(
            accessToken
          )
      );

    if (
      userError ||
      !userData.user
    ) {
      return Response.json(
        {
          error:
            "ログイン情報を確認できませんでした。ページを再読み込みしてね。",
        },
        {
          status: 401,
        }
      );
    }

    if (requestId !== undefined && (typeof requestId !== "string" ||
      !/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(requestId))) {
      return Response.json({ error: "Invalid request ID." }, { status: 400 });
    }
    const usageRequestId = requestId || crypto.randomUUID();
    const isAnonymous = userData.user.is_anonymous === true;
    const relationshipSupabase = isAnonymous ? null : createServerSupabase();
    const userMessageAt = new Date().toISOString();
    const temporary = isAnonymous ? openTemporaryState(temporaryState) : null;
    if (isAnonymous && temporary?.requestId === usageRequestId && temporary.result) {
      const { originalMessage, ...replay } = temporary.result;
      if (originalMessage !== message) return Response.json({ error: "Request ID message mismatch." }, { status: 409 });
      after(() => resumeRelationshipProcessing(userData.user.id, true));
      return Response.json(publicChatResult({ ...replay, temporaryState }));
    }
    if (!isAnonymous) {
      const completed = await loadCompletedTurn(userData.user.id, usageRequestId, message);
      if (completed) {
        after(() => resumeRelationshipProcessing(userData.user.id, isAnonymous));
        return Response.json(publicChatResult(completed));
      }
    } else {
      const completed = await loadCompletedTemporaryTurn(userData.user.id, usageRequestId, message, temporaryState);
      if (completed) {
        after(() => resumeRelationshipProcessing(userData.user.id, isAnonymous));
        return Response.json(publicChatResult(completed));
      }
    }
    const rootState = isAnonymous
      ? await loadTemporaryRoot(userData.user.id, temporaryState)
      : await loadCanonicalState(userData.user.id);
    memory = rootState.memory;
    misakiTodayMemory = rootState.todayMemory;
    history = "history" in rootState ? rootState.history : [];
    const canonicalRelationshipPoints = rootState.relationshipPoints;
    const recallMode = isMemoryRecallQuestion(message);
    const modelMessage = createRecallAwareMessage(message, history, recallMode);

    const relationshipTimeContext = isAnonymous
      ? rootState.temporaryRelationship
        ? {
            exists: true,
            elapsedSeconds: rootState.temporaryRelationship.lastInteractionAt
              ? Math.max(0, (Date.now() - Date.parse(rootState.temporaryRelationship.lastInteractionAt)) / 1000) : 0,
            elapsedHours: rootState.temporaryRelationship.lastInteractionAt
              ? Math.max(0, (Date.now() - Date.parse(rootState.temporaryRelationship.lastInteractionAt)) / 3600000) : 0,
            timeBand: "temporary",
            intimacyLevel: canonicalRelationshipPoints >= 160 ? "very_intimate"
              : canonicalRelationshipPoints >= 80 ? "intimate"
              : canonicalRelationshipPoints >= 30 ? "growing" : "initial",
            intimacyPoints: canonicalRelationshipPoints,
            emotionPrimary: rootState.temporaryRelationship.emotionPrimary,
            emotionIntensity: rootState.temporaryRelationship.emotionIntensity,
            actionState: rootState.temporaryRelationship.actionState,
            lastInteractionAt: rootState.temporaryRelationship.lastInteractionAt,
            stateUpdatedAt: null,
          }
        : null
      : await measureStage(
          "relationship-time-load",
          () => loadRelationshipTimeContext(relationshipSupabase!, false, userData.user.id)
        );
    const anonymousRelationshipEvents =
      isAnonymous && Array.isArray(rootState.temporaryRelationship?.events)
        ? rootState.temporaryRelationship.events.slice(-40)
        : [];
    const relationshipHistory = isAnonymous
      ? {
          patterns: deriveRelationshipPatterns(anonymousRelationshipEvents),
          story: deriveRelationshipStory(anonymousRelationshipEvents),
        }
      : await measureStage(
          "relationship-history-load",
          () => loadRelationshipHistory(relationshipSupabase! as any, false)
        );
    const relationshipPatterns = relationshipHistory.patterns;
    const relationshipStory = relationshipHistory.story;


    const {
      data: usageData,
      error: usageError,
    } =
      await measureStage(
        "usage-consume",
        () =>
          consumeDailyMessageWithRetry(
            supabase,
            usageRequestId
          )
      );

    if (usageError) {
      return Response.json(
        {
          error:
            "利用回数を確認できませんでした。少ししてからもう一度試してね。",
        },
        {
          status: 500,
        }
      );
    }

    const usage =
      getFirstRow<UsageResult>(
        usageData
      );

    if (!usage) {
      return Response.json(
        {
          error:
            "利用回数を確認できませんでした。少ししてからもう一度試してね。",
        },
        {
          status: 500,
        }
      );
    }

    if (
      usage.allowed === true &&
      usage.is_premium !== true
    ) {
      chargedRequestId =
        usageRequestId;
      chargedSupabase =
        supabase;
    }

    if (
      usage.allowed !== true &&
      usage.is_premium !== true
    ) {
      return Response.json(
        {
          error:
            "今日は無料分の20回まで話したよ。",
          usage: {
            messageCount:
              typeof usage.message_count ===
              "number"
                ? usage.message_count
                : 20,
            remaining:
              typeof usage.remaining ===
              "number"
                ? usage.remaining
                : 0,
            isPremium: false,
          },
        },
        {
          status: 429,
        }
      );
    }

    const safeHistory:
      ChatMessage[] =
      Array.isArray(history)
        ? history
            .filter(
              (item) =>
                item &&
                (
                  item.role ===
                    "user" ||
                  item.role ===
                    "misaki"
                ) &&
                typeof item.text ===
                  "string"
            )
            .slice(-MAX_HISTORY)
        : [];

    const safeMemory:
      string[] =
      Array.isArray(memory)
        ? memory
            .filter(
              (item) =>
                typeof item ===
                "string"
            )
            .map(
              (item) =>
                item.trim()
            )
            .filter(Boolean)
            .slice(-MAX_MEMORY)
        : [];

    const safeCurrentTime =
      typeof currentTime ===
      "string"
        ? currentTime
        : "不明";

    const splitMemory = splitLifeFactMemory(safeMemory);
    const explicitLifeFacts = extractExplicitLifeFacts(message, safeCurrentTime);
    const lifeFacts: LifeFact[] = [
      ...splitMemory.ordinaryMemory.map((fact) => ({ kind: "profile" as const, fact, source: "memory" as const, confidence: 1 })),
      ...splitMemory.facts,
      ...explicitLifeFacts,
    ];
    const lifeUnderstandingGuide = createLifeUnderstandingGuide(selectRelevantLifeFacts(lifeFacts, safeCurrentTime));

    const currentDate =
      getDateKey(
        safeCurrentTime
      );

    const safeTodayMemory:
      MisakiTodayMemory = {
      date:
        misakiTodayMemory &&
        typeof misakiTodayMemory.date ===
          "string"
          ? misakiTodayMemory.date
          : currentDate,
      items:
        misakiTodayMemory &&
        Array.isArray(
          misakiTodayMemory.items
        )
          ? misakiTodayMemory.items
              .filter(
                (item: unknown) =>
                  typeof item ===
                    "string"
              )
              .map(
                (item: string) =>
                  item.trim()
              )
              .filter(Boolean)
              .slice(
                -MAX_TODAY_MEMORY
              )
          : [],
    };

    if (
      safeTodayMemory.date !==
      currentDate
    ) {
      safeTodayMemory.date =
        currentDate;
      safeTodayMemory.items = [];
    }

    const userMessageCount =
      safeHistory.filter(
        (item) =>
          item.role === "user"
      ).length;

    const safeRelationshipPoints = canonicalRelationshipPoints;

    const relationshipGuide = engineEnabled() ? "" :
      createRelationshipGuide(
        safeRelationshipPoints
      );

    const relationshipActingGuide =
      createRelationshipActingGuide(
        rootState.relationshipActingState ?? (rootState.relationshipEngine ? { ...rootState.relationshipEngine.state, intimacyStage: createLegacyRelationshipActingState(safeRelationshipPoints).intimacyStage } : undefined) ?? createLegacyRelationshipActingState(
          safeRelationshipPoints
        )
      );

    const userProfile =
      buildUserProfile(
        [
          ...safeHistory,
          {
            role: "user",
            text: message,
          },
        ],
        safeMemory
      );

    const userProfileGuide =
      createUserProfileGuide(
        userProfile
      );

    const taxiContextGuide =
      createTaxiContextGuide(
        userProfile
      );

    const loadedPersona =
      await measureStage(
        "persona-load",
        () =>
          loadPersonaPrompt(
            supabase,
            userData.user.id,
            "chat",
            relationshipTimeContext
          )
      );

    const personaPrompt =
      loadedPersona.text;

    console.log(
      "MISAKI PERSONA:",
      {
        source:
          loadedPersona.source,
        version:
          loadedPersona.versionCode,
      }
    );

    const memoryText =
      safeMemory.length > 0
        ? safeMemory
            .map(
              (item) =>
                `・${item}`
            )
            .join("\n")
        : "まだ長期記憶はありません。";

    const misakiLifeContext =
      createMisakiLife(
        safeCurrentTime
      );

    const misakiDayType =
      misakiLifeContext.dayType;

    const misakiLife =
      misakiLifeContext.guide;

    const timeGuide =
      createTimeGuide(
        safeCurrentTime
      );

    const todayMemoryGuide =
      createTodayMemoryGuide(
        safeTodayMemory,
        currentDate
      );

    const activityEvidence =
      buildActivityEvidence(
        safeHistory,
        safeTodayMemory
      );

    const activityGroundingGuide =
      createActivityGroundingGuide(
        activityEvidence
      );

    const [
      tokyoWeather,
      tokyoLifeEvents,
    ] =
      await Promise.all([
        measureStage(
          "weather",
          () =>
            getTokyoWeather()
        ),
        measureStage(
          "life-events",
          () =>
            getTokyoLifeEvents()
        ),
      ]);

    const weatherGuide =
      createWeatherGuide(
        tokyoWeather
      );

    const tokyoLifeEventsGuide =
      createTokyoLifeEventsGuide(
        tokyoLifeEvents,
        userProfile
      );

    const recentMisakiMessages =
      safeHistory
        .filter(
          (item) =>
            item.role === "misaki"
        )
        .slice(-8)
        .map(
          (item) => item.text
        );

    const recentTopicText =
      recentMisakiMessages.length >
      0
        ? recentMisakiMessages
            .map(
              (text) =>
                `・${text}`
            )
            .join("\n")
        : "なし";

    const weatherHistoryGuide =
      hasRecentMisakiWeatherContext(
        safeHistory
      )
        ? `
【直前の天気会話について】

直近の会話履歴に
美咲自身の天気発言があります。

その発言を根拠に、
「さっきと変わらず」
「さっきと同じ」
「さっきより少し〜」
などの比較はできます。

ただし、
履歴から確認できない継続時間まで
作らないでください。
`.trim()
        : `
【直前の天気会話について】

直近の会話履歴に
美咲自身の天気発言はありません。

「さっきと変わらず」
「さっきと同じ」
「さっきより」
などの比較を
勝手に作らないでください。
`.trim();

    const contents: Array<{
      role: "user" | "model";
      parts: Array<{ text: string }>;
    }> =
      safeHistory.map(
        (item) => ({
          role:
            item.role === "user"
              ? "user"
              : "model",
          parts: [
            {
              text: item.text,
            },
          ],
        })
      );

    const baseSystemPrompt = `
${personaPrompt}

${relationshipGuide}

${relationshipActingGuide}
${pendingRelationshipGuide(rootState)}

${userProfileGuide}

${lifeUnderstandingGuide}

${createRelationshipTimeGuide(relationshipTimeContext)}

${createRelationshipSignalGuide()}

${taxiContextGuide}

【ユーザーの今日の仕事・休みについて】

ユーザーが今日仕事か休みかは、
現在の会話・直近履歴・長期記憶に
明確な根拠がある場合だけ使ってください。

根拠がないのに、
「今日も仕事頑張ってね」
「お仕事お疲れ様」
「これから仕事？」
などと決めつけないでください。

分からない場合は、
仕事か休みかに触れず自然に返してください。

${misakiLife}

【美咲の仕事日・休日は固定】

今日が仕事の日なら、
今日の会話中ずっと仕事の日です。

今日が休みの日なら、
今日の会話中ずっと休みの日です。

「今ゆっくりしている」と
「今日は休み」は別です。

${activityGroundingGuide}

【リアルタイム情報の入手経路を作らない】

天気・交通・羽田・地震・警報について、

「ニュースで見た」
「SNSで見た」
「スマホで見た」
「天気予報だと」
「予報で言ってた」

など、
美咲が実際に情報を見聞きしたような
架空の経路は禁止です。

与えられた情報を、
今の二人の関係段階に合う自然な会話として
そのまま使ってください。

【現在日時】

${safeCurrentTime}

${timeGuide}

${weatherGuide}

${weatherHistoryGuide}

${tokyoLifeEventsGuide}

【天気についての最重要ルール】

天気について使える根拠は
次の3つを区別してください。

1. 現在の気象観測
2. 短時間予報
3. 直前の会話履歴

現在観測だけから、
過去の天気経過を作らないでください。

ユーザーが美咲側の天気を聞いた場合は、
美咲側の現在天気と
確認できている短時間予報を中心に答えてください。

「そっちは？」
と機械的に質問し返したり、
傘などの行動アドバイスを
勝手に追加しないでください。

${todayMemoryGuide}

【直近の美咲の発言】

${recentTopicText}

同じ表現を
そのまま繰り返さないでください。

【長期記憶】

${memoryText}

必要なときだけ自然に使ってください。

【今日の記憶に保存するルール】

misakiTodayMemory は、
美咲自身について
今日実際に会話で確定した出来事だけを保存します。

架空の過去行動や、
仕事日／休日と矛盾する出来事を
新しく保存しないでください。

【出力】

必ずJSONだけを返してください。

{
  "reply": "美咲の返事",
  "memory": ["長期記憶"],
  "relationshipSignals": {
    "signals": [],
    "relationshipFacts": {
      "mutualAffectionExplicit": false,
      "datingEstablishedExplicit": false
    }
  },
  "misakiTodayMemory": {
    "date": "${currentDate}",
    "items": ["今日の美咲の出来事"]
  }
}
`.trim();

    async function generateReply(
      retryProblems?: string[],
      supplementaryGuide = ""
    ) {
      const retryGuide =
        retryProblems &&
        retryProblems.length > 0
          ? `

【前の返答は不採用】

問題：
${retryProblems
  .map(
    (problem) =>
      `・${problem}`
  )
  .join("\n")}

最初から作り直してください。

今日の美咲は
「${
  misakiDayType === "work"
    ? "仕事の日"
    : "休みの日"
}」です。

美咲自身の具体的な過去行動は、
会話履歴または今日の記憶に
根拠がある場合だけ使ってください。

ユーザーの職業・居住地・名前も、
会話または長期記憶に
根拠があるものだけ使ってください。

名前を知っていても
毎回名前を呼ばないでください。

天気について、
架空の情報入手経路や
確認できない時間経過を
作らないでください。

必ずJSONだけを返してください。
`
          : "";
      const startedAt = Date.now();
      const attempt =
        retryProblems && retryProblems.length > 0
          ? "retry"
          : "initial";
      const hasSupplementaryUnicode =
        /[\uD800-\uDBFF][\uDC00-\uDFFF]/.test(message);

      console.log("GEMINI FETCH START:", {
        traceId,
        attempt,
        messageLength: message.length,
        hasSupplementaryUnicode,
      });

      try {
        const result = await generateGeminiJson({
          telemetrySink: createGeminiTelemetrySink("normal_reply", userData.user.id, usageRequestId),
          apiKey,
          systemInstruction:
            baseSystemPrompt +
            retryGuide +
            supplementaryGuide,
          contents,
          userText: modelMessage,
          timeoutMs: GEMINI_TIMEOUT_MS,
        });

        const elapsedMs = Date.now() - startedAt;
        console.log("GEMINI FETCH END:", {
          traceId,
          attempt,
          status: result.status,
          elapsedMs,
        });

        if (!result.ok) {
          console.error("GEMINI API ERROR:", {
            traceId,
            attempt,
            status: result.status,
            elapsedMs,
            data: result.data,
          });
          return null;
        }

        return parseGeminiText(result.text);
      } catch (error) {
        const elapsedMs = Date.now() - startedAt;

        if (
          error instanceof Error &&
          error.name === "AbortError"
        ) {
          console.error("GEMINI FETCH TIMEOUT:", {
            traceId,
            attempt,
            elapsedMs,
            messageLength: message.length,
            hasSupplementaryUnicode,
          });

          throw new Error("GEMINI_TIMEOUT");
        }

        console.error("GEMINI FETCH FAILED:", {
          traceId,
          attempt,
          elapsedMs,
          error,
        });
        throw error;
      }
    }

    let parsed =
      await generateReply();

    if (!parsed) {
      const refunded =
        await refundIfCharged();

      return Response.json(
        {
          error:
            "美咲の返事をうまく読み取れなかったみたい。もう一度話しかけてね。",
          ...(refunded
            ? {
                usage: {
                  messageCount:
                    refunded.message_count ?? 0,
                  remaining:
                    refunded.remaining ?? 0,
                  isPremium:
                    refunded.is_premium === true,
                },
              }
            : {}),
        },
        {
          status: 500,
        }
      );
    }

    let reply =
      typeof parsed.reply ===
      "string"
        ? parsed.reply.trim()
        : "";

    if (!reply) {
      const refunded =
        await refundIfCharged();

      return Response.json(
        {
          error:
            "美咲から返事が来なかったみたい。もう一度話しかけてね。",
          ...(refunded
            ? {
                usage: {
                  messageCount:
                    refunded.message_count ?? 0,
                  remaining:
                    refunded.remaining ?? 0,
                  isPremium:
                    refunded.is_premium === true,
                },
              }
            : {}),
        },
        {
          status: 500,
        }
      );
    }

    const firstProblems =
      getReplyProblems(
        reply,
        message,
        safeCurrentTime,
        safeHistory,
        activityEvidence,
        misakiDayType
      );

    if (
      firstProblems.length > 0
    ) {
      console.log(
        "MISAKI REPLY RETRY:",
        firstProblems
      );

      const retryParsed =
        await generateReply(
          firstProblems
        );

      if (
        retryParsed &&
        typeof retryParsed.reply ===
          "string" &&
        retryParsed.reply.trim()
      ) {
        parsed = retryParsed;
        reply =
          retryParsed.reply.trim();
      }
    }

    reply =
      cleanFinalReply(
        reply,
        message,
        activityEvidence,
        misakiDayType
      );

    const relationshipAssessment: RelationshipSignalAssessment =
      sanitizeRelationshipSignalAssessment(parsed.relationshipSignals);
    const relationshipPointDelta = deriveRelationshipPointDelta(relationshipAssessment);
    const relationshipPreview = previewRelationshipTurn(
      relationshipTimeContext,
      relationshipAssessment,
      relationshipPatterns
    );
    const relationshipActionGuide =
      createCurrentTurnActionGuide(
        relationshipPreview.action,
        relationshipPreview.emotion.afterglow,
        relationshipPreview.emotion.secondary,
        relationshipStory
      );

    if (relationshipAssessment.signals.length > 0 && relationshipActionGuide) {
      const expressionParsed = await generateReply(
        [],
        `

【今回の関係状態に合わせた表現調整】

${relationshipActionGuide}

意味・事実・記憶候補は変えず、返答の温度と距離感だけをこの状態に合わせてください。
relationshipSignals は最初の判定をやり直さず、同じ意味を保ってください。
`
      );
      if (expressionParsed?.reply?.trim()) {
        reply = cleanFinalReply(
          expressionParsed.reply.trim(),
          message,
          activityEvidence,
          misakiDayType
        );
      }
    }

    const finalProblems =
      getReplyProblems(
        reply,
        message,
        safeCurrentTime,
        safeHistory,
        activityEvidence,
        misakiDayType
      );

    if (
      finalProblems.length > 0
    ) {
      console.warn(
        "MISAKI FINAL REPLY PROBLEMS:",
        finalProblems,
        reply
      );
    }

    const generatedMemory =
      recallMode ? splitMemory.ordinaryMemory : Array.isArray(parsed.memory)
        ? parsed.memory.filter((item) => typeof item === "string").map((item) => item.trim()).filter(Boolean)
        : splitMemory.ordinaryMemory;
    const activeCarriedLifeFacts = selectRelevantLifeFacts(splitMemory.facts, safeCurrentTime, MAX_MEMORY);
    const activeLifeFacts = selectRelevantLifeFacts([...activeCarriedLifeFacts, ...explicitLifeFacts], safeCurrentTime, MAX_MEMORY);
    const encodedLifeMemory = activeLifeFacts.map((fact) => encodeLifeFactMemory(fact));
    const updatedMemory = [
      ...generatedMemory.filter((item) => !item.startsWith("[life:v1]")),
      ...encodedLifeMemory,
    ].slice(-MAX_MEMORY);

    const parsedTodayItems =
      Array.isArray(
        parsed
          .misakiTodayMemory
          ?.items
      )
        ? parsed
            .misakiTodayMemory!
            .items!
            .filter(
              (item) =>
                typeof item ===
                  "string"
            )
            .map(
              (item) =>
                item.trim()
            )
            .filter(Boolean)
        : safeTodayMemory.items;

    const safeNewTodayItems =
      parsedTodayItems.filter(
        (item) => {
          if (
            safeTodayMemory.items.includes(
              item
            )
          ) {
            return true;
          }

          if (
            findUnsupportedActivityGroups(
              item,
              activityEvidence
            ).length > 0
          ) {
            return false;
          }

          if (
            findDayTypeProblems(
              item,
              misakiDayType
            ).length > 0
          ) {
            return false;
          }

          return true;
        }
      );

    const updatedTodayMemory:
      MisakiTodayMemory = {
      date: currentDate,
      items:
        Array.from(
          new Set([
            ...safeTodayMemory.items,
            ...safeNewTodayItems,
          ])
        ).slice(
          -MAX_TODAY_MEMORY
        ),
    };

    const generatedResult = {
      requestId: usageRequestId,
      rootUpdatedAt: rootState.updatedAt ?? null,
      reply,
      memory:
        updatedMemory,
      misakiTodayMemory:
        updatedTodayMemory,
      relationshipPoints:
        safeRelationshipPoints,
      relationshipPointDelta,
      usage: {
        messageCount:
          typeof usage.message_count ===
          "number"
            ? usage.message_count
            : 0,
        remaining:
          typeof usage.remaining ===
          "number"
            ? usage.remaining
            : 0,
        isPremium:
          usage.is_premium ===
          true,
      },
    };
    let completedResult: Record<string, unknown>;
    if (isAnonymous) {
      completedResult = { ...generatedResult, relationshipPoints: Math.max(0, canonicalRelationshipPoints + relationshipPointDelta),
        memorySynced: false, relationshipTimeSynced: false, ephemeral: true };
      const token = sealTemporaryState({ memory: updatedMemory, todayMemory: updatedTodayMemory,
        relationshipEngine: enqueueTemporaryTurn(rootState, { requestId: usageRequestId, message: message.slice(0, 2000), reply: reply.slice(0, 2000), savedAt: new Date().toISOString() }),
        relationshipPoints: Math.max(0, canonicalRelationshipPoints + relationshipPointDelta),
        temporaryRelationship: {
          emotionPrimary: relationshipPreview.emotion.primary,
          emotionIntensity: relationshipPreview.emotion.intensity,
          actionState: relationshipPreview.action.action,
          lastInteractionAt: new Date().toISOString(),
          signals: relationshipAssessment.signals.map(({ name, strength, confidence }) => ({ name, strength, confidence })),
          events: [...anonymousRelationshipEvents, {
            event_type: "emotion_action_v2_after_chat" as const,
            created_at: new Date().toISOString(),
            metadata: {
              signal_summary: relationshipAssessment.signals.map(({ name, strength, confidence }) => ({
                name, strength, confidence,
              })),
            },
          }].slice(-40),
        },
        history: [...(Array.isArray(history) ? history : []),
          { role: "user", text: message, sentAt: userMessageAt, requestId: usageRequestId },
          { role: "misaki", text: reply, sentAt: new Date().toISOString(), requestId: usageRequestId }].slice(-MAX_HISTORY)
          .map((item: any) => ({ ...item, text: String(item.text).slice(0, 2000) }))
      }, usageRequestId, { ...completedResult, originalMessage: message });
      completedResult = await completeTemporaryTurn(userData.user.id, usageRequestId, message, temporaryState, token, rootState.temporaryRevision ?? null);
    } else {
      completedResult = await completeCanonicalTurn(userData.user.id, usageRequestId, message,
        userMessageAt, generatedResult);
    }
    chargedRequestId = null;
    chargedSupabase = null;
    after(async () => {
      try {
    if (!isAnonymous) {
      await measureStage(
        "relationship-emotion-persist",
        () => persistRelationshipEmotionFromSignals(
          relationshipSupabase!,
          false,
          relationshipTimeContext,
          relationshipAssessment,
          relationshipPatterns,
          userData.user.id
        )
      );
    }

    if (!isAnonymous) {
      await measureStage(
        "relationship-turn-record",
        () => recordRelationshipChatTurn(
          relationshipSupabase!,
          false,
          new Date(requestStartedAt),
          new Date(),
          userData.user.id
        )
      );
    }

      } catch { console.error("POST SAVE LEGACY RELATIONSHIP RETRY REQUIRED", { traceId }); }
      await resumeRelationshipProcessing(userData.user.id, isAnonymous);
    });
    console.log(
      "CHAT TOTAL:",
      {
        traceId,
        elapsedMs:
          Date.now() -
          requestStartedAt,
        ok: true,
      }
    );

    return Response.json(publicChatResult(completedResult));
  } catch (error) {
    console.error(
      "CHAT ROUTE ERROR:",
      {
        traceId,
        elapsedMs:
          Date.now() -
          requestStartedAt,
        error,
      }
    );

    const refunded =
      await refundIfCharged();

    console.log(
      "CHAT TOTAL:",
      {
        traceId,
        elapsedMs:
          Date.now() -
          requestStartedAt,
        ok: false,
      }
    );

    return Response.json(
      {
        error:
          "今ちょっと美咲とつながりにくいみたい。少ししてからもう一度話しかけてね。",
        ...(refunded
          ? {
              usage: {
                messageCount:
                  refunded.message_count ?? 0,
                remaining:
                  refunded.remaining ?? 0,
                isPremium:
                  refunded.is_premium === true,
              },
            }
          : {}),
      },
      {
        status: 500,
      }
    );
  }
}

